import{_ as s,o as i,c as a,a3 as t}from"./chunks/framework.vDgOMd_y.js";const k=JSON.parse('{"title":"Agent Skills","description":"","frontmatter":{},"headers":[],"relativePath":"en/customization/skills.md","filePath":"en/customization/skills.md"}'),n={name:"en/customization/skills.md"};function l(o,e,d,r,c,h){return i(),a("div",null,[...e[0]||(e[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/customization/skills.md for this page in Markdown format</div><h1 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h1><p>Agent Skills are a lightweight mechanism for extending model capabilities in Kimi Code CLI. A Skill is a Markdown document with YAML frontmatter that describes a specialized area of knowledge or a workflow — for example, a project&#39;s code style guidelines, a PR review process, or a commit message format.</p><p>Compared to pasting the same instructions into a prompt every time, Skills offer the advantage of keeping content in a file, enabling reuse across projects and teams, allowing instant loading via a slash command, and letting the model invoke them automatically when needed.</p><h2 id="creating-a-skill" tabindex="-1">Creating a Skill <a class="header-anchor" href="#creating-a-skill" aria-label="Permalink to &quot;Creating a Skill&quot;">​</a></h2><p>Skill files must be placed in a <a href="#skill-locations">known scan directory</a>. Two file structures are supported:</p><ul><li><strong>Directory form (recommended)</strong>: Create a subdirectory under the Skills directory, name the main file <code>SKILL.md</code>, and place scripts, reference materials, and other supporting files in the same directory. When both <code>&lt;name&gt;/SKILL.md</code> and a same-named <code>&lt;name&gt;.md</code> exist in the same directory, the subdirectory takes precedence.</li><li><strong>Flat form</strong>: Use a single <code>.md</code> file directly; the Skill name is taken from the filename (minus <code>.md</code>).</li></ul><h3 id="file-format" tabindex="-1">File Format <a class="header-anchor" href="#file-format" aria-label="Permalink to &quot;File Format&quot;">​</a></h3><p><code>SKILL.md</code> consists of two parts: YAML frontmatter and a Markdown body:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: code-style</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Project code style guidelines defining naming, indentation, comments, and file organization</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type: prompt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">whenToUse: When the user asks me to write, modify, or review project source code</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disableModelInvocation: false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">arguments:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> target</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mode</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Please handle code according to the following guidelines:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use 2-space indentation</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Variable names use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`camelCase\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, type names use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`PascalCase\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Public functions must have TSDoc comments</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Lines must not exceed 100 characters</span></span></code></pre></div><h3 id="frontmatter-fields" tabindex="-1">Frontmatter Fields <a class="header-anchor" href="#frontmatter-fields" aria-label="Permalink to &quot;Frontmatter Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>Skill name. Required in a directory-form <code>SKILL.md</code>; when omitted in a flat <code>.md</code> file, the filename is used. Names are case-insensitive</td></tr><tr><td><code>description</code></td><td>A one-line summary; the model uses this to decide when to use the Skill. Required in a directory-form <code>SKILL.md</code>; when omitted in a flat <code>.md</code> file, falls back to the first non-empty line of the body (up to 240 characters)</td></tr><tr><td><code>type</code></td><td>Skill type: <code>prompt</code> (default), <code>inline</code> (same semantics as <code>prompt</code>), <code>flow</code> (manual invocation only; not available for automatic model invocation). Other values are skipped</td></tr><tr><td><code>whenToUse</code></td><td>Description of when the Skill should be triggered. Also accepts <code>when-to-use</code> and <code>when_to_use</code></td></tr><tr><td><code>disableModelInvocation</code></td><td>When set to <code>true</code>, prevents the model from invoking this Skill automatically. Also accepts <code>disable-model-invocation</code> and <code>disable_model_invocation</code></td></tr><tr><td><code>arguments</code></td><td>List of named parameters; can be written as a string array or a whitespace-separated string (e.g., <code>arguments: target mode</code>). Once declared, parameters can be read in the body with <code>$&lt;name&gt;</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Note</p><p>In a directory-form <code>SKILL.md</code>, both <code>name</code> and <code>description</code> <strong>must</strong> be explicitly provided. Omitting either one will cause parsing to fail.</p></div><h3 id="body-placeholders" tabindex="-1">Body Placeholders <a class="header-anchor" href="#body-placeholders" aria-label="Permalink to &quot;Body Placeholders&quot;">​</a></h3><p>Before the body is sent to the model, a small set of placeholders are expanded:</p><ul><li><code>$ARGUMENTS</code>: The full raw argument string passed at invocation</li><li><code>$ARGUMENTS[0]</code>, <code>$ARGUMENTS[1]</code> and shorthand <code>$0</code>, <code>$1</code>: Positional arguments after whitespace tokenization (zero-indexed)</li><li><code>$&lt;name&gt;</code>: Named parameters declared in <code>arguments</code></li><li><code>\${KIMI_SKILL_DIR}</code>: The directory containing the current Skill file</li></ul><p>Positional arguments support single and double quoting, so in <code>/skill:commit &quot;fix login&quot; patch</code>, <code>$0</code> expands to <code>fix login</code>. If the body contains no argument placeholders, text passed at invocation is appended to the end of the body as <code>\\n\\nARGUMENTS: &lt;text&gt;</code>.</p><h2 id="skill-locations" tabindex="-1">Skill Locations <a class="header-anchor" href="#skill-locations" aria-label="Permalink to &quot;Skill Locations&quot;">​</a></h2><p>Kimi Code CLI scans four tiers by scope; more specific scopes take higher priority: <strong>Project &gt; User &gt; Extra &gt; Built-in</strong></p><p><strong>User level</strong> (applies to all projects):</p><ul><li><code>$KIMI_CODE_HOME/skills/</code> (default: <code>~/.kimi-code/skills/</code>)</li><li><code>~/.agents/skills/</code></li></ul><p>The Kimi-specific user Skill directory moves with <code>KIMI_CODE_HOME</code>, so isolated data roots also get isolated Kimi-specific Skills. The generic <code>~/.agents/skills/</code> directory stays under the real OS home so it can be shared across tools.</p><p><strong>Project level</strong> (project root = the nearest directory containing <code>.git</code>, searching upward from the working directory):</p><ul><li><code>.kimi-code/skills/</code></li><li><code>.agents/skills/</code></li></ul><p><strong>Extra directories</strong>: Declared via <code>extra_skill_dirs</code> at the top level of <code>config.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">extra_skill_dirs = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/team-skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.agents/team-skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><strong>Built-in Skills</strong> are distributed with the CLI and have the lowest priority. They provide out-of-the-box workflows for common tasks — for example, configuring MCP servers, customizing the TUI theme, and editing config files. See <a href="./../reference/slash-commands.html#built-in-skill-commands">Built-in skill commands</a> for the full list. Those describing Kimi Code itself can be turned off with the top-level <a href="./../configuration/config-files.html#top-level-fields"><code>builtin_product_skills</code></a> field.</p><h2 id="invoking-a-skill" tabindex="-1">Invoking a Skill <a class="header-anchor" href="#invoking-a-skill" aria-label="Permalink to &quot;Invoking a Skill&quot;">​</a></h2><p>Users can invoke a Skill manually with a slash command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/skill:code-style</span></span>
<span class="line"><span>/skill:git-commits fix concurrency issue in login endpoint</span></span></code></pre></div><p>The model can also invoke a Skill automatically based on <code>description</code> and <code>whenToUse</code> (unless <code>disableModelInvocation</code> is <code>true</code> or <code>type</code> is <code>flow</code>). Skill invocations allow up to 3 levels of nesting; beyond that they are terminated.</p><h2 id="complete-example" tabindex="-1">Complete Example <a class="header-anchor" href="#complete-example" aria-label="Permalink to &quot;Complete Example&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: review-pr</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Review a Pull Request according to team standards and produce a structured review report</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type: prompt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">whenToUse: When the user asks me to review a PR, inspect code changes, or evaluate commit quality</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">arguments:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pr_ref</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Please review the PR the user specified: $pr_ref</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Fetch and read the full diff for </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`$pr_ref\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Check each of the following items:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Whether corresponding test cases are included</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Whether public API documentation has been updated</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Whether new dependencies have been introduced; if so, state the reason</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Whether error handling covers edge cases</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Refer to the checklist in the same directory: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`references/checklist.md\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Produce a review report containing:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Overall conclusion (approve / request changes / comment)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Required changes (blocking)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Suggested improvements (non-blocking)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Noteworthy positives</span></span></code></pre></div><p>Save this as <code>$KIMI_CODE_HOME/skills/review-pr/SKILL.md</code> (or <code>~/.kimi-code/skills/review-pr/SKILL.md</code> when <code>KIMI_CODE_HOME</code> is unset), place the checklist at <code>references/checklist.md</code> in the same directory, and after starting a new session you can invoke it with <code>/skill:review-pr #1234</code>, where <code>#1234</code> is expanded into <code>$pr_ref</code>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./plugins.html">Plugins</a> — Package Skills into installable units to share with your team</li><li><a href="./agents.html">Agents and sub-agents</a> — How Skills influence sub-agent behavior</li></ul>`,36)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
